#!/bin/bash
#
# Regenerate the GENIE configuration files that are copies of GENIE's own
# config with ExtGen additions. Run this whenever the GENIE version changes:
#
#   setup genie <version> ...   (or set up the uboonecode release)
#   ./make_extgen_gxml.sh [path/to/GENIE/config]
#
# Generated files (do not edit by hand):
#   master_config.xml                    + ExtGen algorithm -> file entries
#   EventGenerator.xml                   + "ExtGenRequest" generation chain
#   GB25_05a/ModelConfiguration.xml      G18_10a copy + XSecModel for ExtGenRequest
#   GB25_05a/CommonParam.xml             G18_10a_02_11a copy + "ExtGen" param set
#
# The tune GB25_05a_00_000 has tuned-parameter set "00", which GENIE treats as
# "configuration only" (TuneId::OnlyConfiguration): it never searches the
# GB25_05a/GB25_05a_00_000/ subdirectory, so every tune file, including
# CommonParam.xml, must be in GB25_05a/.
#
# These directories are put on GXMLPATH only by the ExtGen fcl files. GENIE
# searches GXMLPATH before its own config directory, so the two overrides
# must never be placed in a directory that is on FW_SEARCH_PATH (GENIEHelper
# appends FW_SEARCH_PATH to GXMLPATH for every GENIE job).

set -e

GCONF=${1:-$GENIE/config}
OUT=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)

# The ExtGen tune is built on top of the G18_10a_02_11a configuration files.
SRC_CMC=G18_10a
SRC_TUNE=G18_10a_02_11a
CMC=GB25_05a

for f in master_config.xml EventGenerator.xml \
         $SRC_CMC/ModelConfiguration.xml $SRC_CMC/$SRC_TUNE/CommonParam.xml; do
  [ -f "$GCONF/$f" ] || { echo "ERROR: $GCONF/$f not found" >&2; exit 1; }
done

# Add a "generated" note right after the <?xml ...?> declaration (which must
# stay the first line).
header() {
  sed "1a <!-- GENERATED by ubsim/ExtGen/gxml/make_extgen_gxml.sh from $1\\n     Do not edit by hand; regenerate when the GENIE version changes. -->"
}

# Insert the contents of file $3 before the first line matching $2 (or after
# it if $4 is "after") in file $1, writing to stdout.
insert() {
  awk -v pat="$2" -v ins="$3" -v where="${4:-before}" '
    BEGIN { while ((getline l < ins) > 0) block = block l "\n" }
    !done && $0 ~ pat {
      if (where == "after") { print; printf "%s", block } else { printf "%s", block; print }
      done = 1; next }
    { print }
    END { if (!done) { print "pattern not found: " pat > "/dev/stderr"; exit 1 } }' "$1"
}

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

# --- master_config.xml
cat > $tmp/master.ins <<'XML'
   <!-- ****** ExtGen (external generator) algorithms, ubsim/ExtGen ****** -->
   <config alg="genie::ubext::ExtGenPXSec">                     ExtGenPXSec.xml                     </config>
   <config alg="genie::ubext::ExtGenInteractionListGenerator">  ExtGenInteractionListGenerator.xml  </config>

XML
insert $GCONF/master_config.xml '</genie_config>' $tmp/master.ins \
  | header "$GCONF/master_config.xml" > $OUT/master_config.xml

# --- EventGenerator.xml
cat > $tmp/evgen.ins <<'XML'

  <!--
  ExtGen request chain (ubsim/ExtGen): GENIE only selects the neutrino,
  target, current, energy and vertex; the final state is produced later by
  an external generator (GiBUU, ...) and merged in by ExtGenMerge.
  -->
  <param_set name="ExtGenRequest">
     <param type="string" name="VldContext"> </param>
     <param type="int"    name="NModules">   2                                                      </param>
     <param type="alg"    name="Module-0">   genie::InitialStateAppender/Default                    </param>
     <param type="alg"    name="Module-1">   genie::VertexGenerator/Default                         </param>
     <param type="alg"    name="ILstGen">    genie::ubext::ExtGenInteractionListGenerator/Default   </param>
  </param_set>

XML
insert $GCONF/EventGenerator.xml '^</alg_conf>' $tmp/evgen.ins \
  | header "$GCONF/EventGenerator.xml" > $OUT/EventGenerator.xml

# --- tune: ModelConfiguration.xml
mkdir -p $OUT/$CMC
cat > $tmp/model.ins <<'XML'
  <!-- ExtGen: total cross sections of the external generator (ubsim/ExtGen) -->
  <param type="alg" name="XSecModel@genie::EventGenerator/ExtGenRequest"> genie::ubext::ExtGenPXSec/Default </param>
XML
insert $GCONF/$SRC_CMC/ModelConfiguration.xml '<param_set name="Default">' $tmp/model.ins after \
  | header "$GCONF/$SRC_CMC/ModelConfiguration.xml" > $OUT/$CMC/ModelConfiguration.xml

# --- tune: CommonParam.xml
cat > $tmp/common.ins <<'XML'
  <!--
  ExtGen (ubsim/ExtGen): text table of the external generator's total
  cross sections. Only read if a cross section is missing from the spline
  file (e.g. when making splines with gmkspl); production jobs use splines.
  Environment variables are expanded.
  -->
  <param_set name="ExtGen">
    <param type="string" name="ExtGen-XSecTable"> $EXTGEN_XSEC_TABLE </param>
  </param_set>

XML
insert $GCONF/$SRC_CMC/$SRC_TUNE/CommonParam.xml '</common_Param_list>' $tmp/common.ins \
  | header "$GCONF/$SRC_CMC/$SRC_TUNE/CommonParam.xml" > $OUT/$CMC/CommonParam.xml

echo "Wrote ExtGen GENIE configuration overrides in $OUT from $GCONF"
